CREATE POLICY "lcpp map image read own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'lcpp-map-images' AND (storage.foldername(name))[1] = auth.uid()::text AND public.has_section('s3'::public.app_role));
CREATE POLICY "lcpp map image insert own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'lcpp-map-images' AND (storage.foldername(name))[1] = auth.uid()::text AND public.has_section('s3'::public.app_role));
CREATE POLICY "lcpp map image update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'lcpp-map-images' AND (storage.foldername(name))[1] = auth.uid()::text AND public.has_section('s3'::public.app_role)) WITH CHECK (bucket_id = 'lcpp-map-images' AND (storage.foldername(name))[1] = auth.uid()::text AND public.has_section('s3'::public.app_role));
CREATE POLICY "lcpp map image delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'lcpp-map-images' AND (storage.foldername(name))[1] = auth.uid()::text AND public.has_section('s3'::public.app_role));